private void failedByException(Throwable th){
  try {
    LOGGER.severe(String.format("%s deploy error with Exception: %s",this.taskFullName,ExceptionUtils.getMessage(th)));
  } catch (IllegalFormatException e) {
    LOGGER.severe("Failed to format error message: " + e.getMessage());
  }
  turnToEndState(ExecutionState.FAILED);
  taskFuture.complete(new TaskExecutionState(this.taskGroupLocation,ExecutionState.FAILED,th));
}
